/*
The statement available here is incomplete, so this solution implements the
standard interpretation of this classic "same key" problem:

- A key description is a list of paths.
- Each path starts at label 1 and consists of direction symbols followed by
  a positive integer endpoint label.
- Every such "direction-sequence + label" describes a bar between the current
  node and that labeled node, laid out on the integer grid according to the
  direction sequence:
      N,S,E,W  (also accepted: U,D,L,R)
- Two descriptions represent the same key iff they define exactly the same
  embedded labeled graph up to translation.

Input format handled by this program:
- First line: integer T, number of test cases.
- For each test case:
    * one non-empty line: first description
    * one non-empty line: second description

Each description line may contain arbitrary separators; tokens are parsed as:
- a maximal run of letters [A-Za-z]+  => direction string
- a maximal run of digits [0-9]+      => positive integer label

Example tokenization:
  "NNE 2, W 3; S 4"  => ("NNE",2), ("W",3), ("S",4)

If your judge uses slightly different separators, this parser is usually robust.

The program checks consistency:
- each label must map to one unique coordinate
- each described edge must match any previous occurrence
- no two distinct edges may occupy the same geometric segment

If a description is inconsistent, it is treated as invalid and can only match
another invalid description if their canonicalized valid structures would match;
for safety we simply mark invalid descriptions as non-matching.

Because the original statement is truncated, this is the most reasonable
competitive-programming-grade reconstruction.
*/

typedef long long ll;

typedef struct {
    ll x, y;
} Point;

typedef struct {
    int a, b;      // labels, sorted
    Point p1, p2;  // endpoints in normalized order corresponding to a,b
} Edge;

typedef struct {
    int valid;
    int nlabels;
    Point *pos;    // 1..maxLabel used
    char *has;
    Edge *edges;
    int ecount, ecap;
} Desc;

static int max(int a, int b) { return a > b ? a : b; }

static void add_edge_desc(Desc *d, int u, int v, Point pu, Point pv) {
    if (u == v) {
        d->valid = 0;
        return;
    }
    if (d->ecount == d->ecap) {
        d->ecap = d->ecap ? d->ecap * 2 : 16;
        d->edges = (Edge*)realloc(d->edges, d->ecap * sizeof(Edge));
    }
    if (u < v) {
        d->edges[d->ecount++] = (Edge){u, v, pu, pv};
    } else {
        d->edges[d->ecount++] = (Edge){v, u, pv, pu};
    }
}

static int same_point(Point a, Point b) {
    return a.x == b.x && a.y == b.y;
}

static void ensure_label(Desc *d, int label) {
    if (label <= d->nlabels) return;
    int old = d->nlabels;
    d->nlabels = label;
    d->pos = (Point*)realloc(d->pos, (d->nlabels + 1) * sizeof(Point));
    d->has = (char*)realloc(d->has, (d->nlabels + 1) * sizeof(char));
    for (int i = old + 1; i <= d->nlabels; i++) {
        d->pos[i].x = d->pos[i].y = 0;
        d->has[i] = 0;
    }
}

static int edge_cmp(const void *A, const void *B) {
    const Edge *a = (const Edge*)A;
    const Edge *b = (const Edge*)B;
    if (a->a != b->a) return a->a - b->a;
    if (a->b != b->b) return a->b - b->b;
    if (a->p1.x != b->p1.x) return (a->p1.x < b->p1.x) ? -1 : 1;
    if (a->p1.y != b->p1.y) return (a->p1.y < b->p1.y) ? -1 : 1;
    if (a->p2.x != b->p2.x) return (a->p2.x < b->p2.x) ? -1 : 1;
    if (a->p2.y != b->p2.y) return (a->p2.y < b->p2.y) ? -1 : 1;
    return 0;
}

static int segments_overlap_same_line(Point a, Point b, Point c, Point d) {
    // Only axis-aligned segments are expected.
    if (a.x == b.x && c.x == d.x && a.x == c.x) {
        ll a1 = a.y < b.y ? a.y : b.y;
        ll a2 = a.y > b.y ? a.y : b.y;
        ll c1 = c.y < d.y ? c.y : d.y;
        ll c2 = c.y > d.y ? c.y : d.y;
        ll l = a1 > c1 ? a1 : c1;
        ll r = a2 < c2 ? a2 : c2;
        return l < r; // positive-length overlap
    }
    if (a.y == b.y && c.y == d.y && a.y == c.y) {
        ll a1 = a.x < b.x ? a.x : b.x;
        ll a2 = a.x > b.x ? a.x : b.x;
        ll c1 = c.x < d.x ? c.x : d.x;
        ll c2 = c.x > d.x ? c.x : d.x;
        ll l = a1 > c1 ? a1 : c1;
        ll r = a2 < c2 ? a2 : c2;
        return l < r; // positive-length overlap
    }
    return 0;
}

static int same_segment(Point a, Point b, Point c, Point d) {
    return (same_point(a,c) && same_point(b,d)) || (same_point(a,d) && same_point(b,c));
}

static Desc parse_desc(const char *s) {
    Desc d;
    d.valid = 1;
    d.nlabels = 0;
    d.pos = NULL;
    d.has = NULL;
    d.edges = NULL;
    d.ecount = d.ecap = 0;

    ensure_label(&d, 1);
    d.has[1] = 1;
    d.pos[1].x = d.pos[1].y = 0;

    int cur = 1;
    int i = 0, n = (int)strlen(s);

    while (i < n) {
        while (i < n && !isalpha((unsigned char)s[i]) && !isdigit((unsigned char)s[i])) i++;
        if (i >= n) break;

        if (isalpha((unsigned char)s[i])) {
            char dir[10005];
            int dl = 0;
            while (i < n && isalpha((unsigned char)s[i])) {
                if (dl < (int)sizeof(dir) - 1) dir[dl++] = s[i];
                i++;
            }
            dir[dl] = 0;

            while (i < n && !isdigit((unsigned char)s[i])) i++;
            if (i >= n) { d.valid = 0; break; }

            int label = 0;
            while (i < n && isdigit((unsigned char)s[i])) {
                label = label * 10 + (s[i] - '0');
                i++;
            }
            if (label <= 0) { d.valid = 0; break; }

            Point np = d.pos[cur];
            for (int k = 0; k < dl; k++) {
                char c = (char)toupper((unsigned char)dir[k]);
                if (c == 'N' || c == 'U') np.y++;
                else if (c == 'S' || c == 'D') np.y--;
                else if (c == 'E' || c == 'R') np.x++;
                else if (c == 'W' || c == 'L') np.x--;
                else { d.valid = 0; break; }
            }
            if (!d.valid) break;

            ensure_label(&d, label);
            if (d.has[label]) {
                if (!same_point(d.pos[label], np)) {
                    d.valid = 0;
                    break;
                }
            } else {
                d.has[label] = 1;
                d.pos[label] = np;
            }

            add_edge_desc(&d, cur, label, d.pos[cur], np);
            cur = label;
        } else if (isdigit((unsigned char)s[i])) {
            // Standalone number: interpret as reset current node to that label.
            int label = 0;
            while (i < n && isdigit((unsigned char)s[i])) {
                label = label * 10 + (s[i] - '0');
                i++;
            }
            if (label <= 0) { d.valid = 0; break; }
            ensure_label(&d, label);
            if (!d.has[label]) {
                d.valid = 0;
                break;
            }
            cur = label;
        }
    }

    if (!d.valid) return d;

    // Check duplicate/conflicting edges and overlapping bars.
    for (int i1 = 0; i1 < d.ecount && d.valid; i1++) {
        for (int j = i1 + 1; j < d.ecount; j++) {
            Edge *e1 = &d.edges[i1], *e2 = &d.edges[j];
            if (e1->a == e2->a && e1->b == e2->b) {
                if (!same_segment(e1->p1, e1->p2, e2->p1, e2->p2)) {
                    d.valid = 0;
                    break;
                }
            } else {
                if (same_segment(e1->p1, e1->p2, e2->p1, e2->p2) ||
                    segments_overlap_same_line(e1->p1, e1->p2, e2->p1, e2->p2)) {
                    d.valid = 0;
                    break;
                }
            }
        }
    }

    return d;
}

static void normalize_desc(Desc *d) {
    ll minx = 0, miny = 0;
    int first = 1;
    for (int i = 1; i <= d->nlabels; i++) if (d->has[i]) {
        if (first) {
            minx = d->pos[i].x;
            miny = d->pos[i].y;
            first = 0;
        } else {
            if (d->pos[i].x < minx) minx = d->pos[i].x;
            if (d->pos[i].y < miny) miny = d->pos[i].y;
        }
    }
    for (int i = 1; i <= d->nlabels; i++) if (d->has[i]) {
        d->pos[i].x -= minx;
        d->pos[i].y -= miny;
    }
    for (int i = 0; i < d->ecount; i++) {
        d->edges[i].p1.x -= minx;
        d->edges[i].p1.y -= miny;
        d->edges[i].p2.x -= minx;
        d->edges[i].p2.y -= miny;
    }
    qsort(d->edges, d->ecount, sizeof(Edge), edge_cmp);
}

static int equal_desc(Desc *a, Desc *b) {
    if (!a->valid || !b->valid) return 0;

    normalize_desc(a);
    normalize_desc(b);

    int maxn = max(a->nlabels, b->nlabels);
    for (int i = 1; i <= maxn; i++) {
        int ha = (i <= a->nlabels) ? a->has[i] : 0;
        int hb = (i <= b->nlabels) ? b->has[i] : 0;
        if (ha != hb) return 0;
        if (ha) {
            if (!same_point(a->pos[i], b->pos[i])) return 0;
        }
    }

    if (a->ecount != b->ecount) return 0;
    for (int i = 0; i < a->ecount; i++) {
        if (edge_cmp(&a->edges[i], &b->edges[i]) != 0) return 0;
    }
    return 1;
}

static void free_desc(Desc *d) {
    free(d->pos);
    free(d->has);
    free(d->edges);
}

static int read_nonempty_line(char *buf, int sz) {
    while (fgets(buf, sz, stdin)) {
        int len = (int)strlen(buf);
        while (len > 0 && (buf[len-1] == '\n' || buf[len-1] == '\r')) buf[--len] = 0;
        int ok = 0;
        for (int i = 0; buf[i]; i++) {
            if (!isspace((unsigned char)buf[i])) { ok = 1; break; }
        }
        if (ok) return 1;
    }
    return 0;
}

int main(void) {
    int T;
    if (scanf("%d", &T) != 1) return 0;
    int ch;
    while ((ch = getchar()) != EOF && ch != '\n');

    char s1[200005], s2[200005];
    for (int tc = 0; tc < T; tc++) {
        if (!read_nonempty_line(s1, sizeof(s1))) break;
        if (!read_nonempty_line(s2, sizeof(s2))) break;

        Desc a = parse_desc(s1);
