/*
The statement as provided is incomplete, but this is the classic "same key"
problem where each key description is a set of axis-aligned paths on the grid.

Each path starts at (0,0). A description consists of several such paths.
A path is given by alternating direction letters and positive integer labels.
For every integer label x appearing after a direction d, we move one unit in
direction d, creating a bar segment, and assign label x to the reached endpoint.

Two descriptions represent the same key iff the induced labeled graph/geometry
is identical up to translation. Since every path starts from the same origin,
translation is fixed; thus we can compare the set of labeled points and the set
of occupied bar positions.

We also must detect invalid descriptions where two bars occupy the same position.

Because the exact input format is omitted in the prompt, this solution supports
the standard format used for such problems:

t
<description 1 of key A>
<description 1 of key B>
...

where each key description is:
n
then n lines, each a path as a string like N1E2S3...

Directions allowed: N,E,S,W.
Numbers are positive integers.

Output SAME / DIFFERENT for each pair.

If your judge uses a slightly different but equivalent tokenization, the parsing
routine can be adapted easily.
*/

struct KeyDesc {
    bool valid = true;
    map<int, pair<int,int>> labelPos; // label -> coordinate
    set<tuple<int,int,int,int>> edges; // normalized undirected unit segments
};

static tuple<int,int,int,int> normEdge(int x1,int y1,int x2,int y2){
    if (make_pair(x2,y2) < make_pair(x1,y1)) swap(x1,x2), swap(y1,y2);
    return {x1,y1,x2,y2};
}

bool parsePath(const string& s, KeyDesc& key){
    int x = 0, y = 0;
    int i = 0, n = (int)s.size();
    while (i < n) {
        char c = s[i];
        if (c!='N' && c!='E' && c!='S' && c!='W') return false;
        ++i;
        if (i >= n || !isdigit((unsigned char)s[i])) return false;
        long long val = 0;
        while (i < n && isdigit((unsigned char)s[i])) {
            val = val * 10 + (s[i]-'0');
            if (val > INT_MAX) return false;
            ++i;
        }
        if (val <= 0) return false;

        int nx = x, ny = y;
        if (c=='N') ny++;
        else if (c=='S') ny--;
        else if (c=='E') nx++;
        else nx--;

        auto e = normEdge(x,y,nx,ny);
        if (key.edges.count(e)) key.valid = false; // overlapping bar
        key.edges.insert(e);

        int label = (int)val;
        auto it = key.labelPos.find(label);
        if (it == key.labelPos.end()) key.labelPos[label] = {nx,ny};
        else if (it->second != make_pair(nx,ny)) key.valid = false;

        x = nx; y = ny;
    }
    return true;
}

bool readKey(istream& in, KeyDesc& key){
    int n;
    if (!(in >> n)) return false;
    key = KeyDesc();
    for (int i = 0; i < n; ++i) {
        string s;
        in >> s;
        if (!parsePath(s, key)) key.valid = false;
    }
    return true;
}

bool sameKey(const KeyDesc& a, const KeyDesc& b){
    if (!a.valid || !b.valid) return false;
    return a.labelPos == b.labelPos && a.edges == b.edges;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    if (!(cin >> T)) return 0;

    while (T--) {
        KeyDesc A, B;
        if (!readKey(cin, A)) return 0;
        if (!readKey(cin, B)) return 0;
        cout << (sameKey(A, B) ? "SAME" : "DIFFERENT") << '\n';
    }
    return 0;
}

