public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int T = sc.nextInt();
        sc.nextLine();

        for (int t = 0; t < T; t++) {
            String line1 = sc.nextLine().trim();
            String line2 = sc.nextLine().trim();

            Set<String> key1 = parseKey(line1);
            Set<String> key2 = parseKey(line2);

            if (key1.equals(key2)) {
                System.out.println("SAME");
            } else {
                System.out.println("DIFFERENT");
            }
        }
        sc.close();
    }

    static Set<String> parseKey(String s) {
        Set<String> edges = new HashSet<>();
        String[] tokens = s.split(" ");
        int x = 0, y = 0;
        int prevX = 0, prevY = 0;

        int i = 0;
        while (i < tokens.length) {
            String dir = tokens[i];
            int num = Integer.parseInt(tokens[i+1]);
            i += 2;

            // move to the endpoint
            switch (dir) {
                case "up": y += num; break;
                case "down": y -= num; break;
                case "left": x -= num; break;
                case "right": x += num; break;
            }

            // add normalized edge
            String edge = normalizeEdge(prevX, prevY, x, y);
            edges.add(edge);

            prevX = x;
            prevY = y;
        }
        return edges;
    }

    static String normalizeEdge(int x1, int y1, int x2, int y2) {
        if (x1 < x2 || (x1 == x2 && y1 < y2)) {
            return x1 + "," + y1 + "-" + x2 + "," + y2;
        } else {
            return x2 + "," + y2 + "-" + x1 + "," + y1;
        }
    }
}

