public class Main {
    static Map<String, int[]> dirs = new HashMap<>();
    static {
        dirs.put("N", new int[]{0,1}); dirs.put("S", new int[]{0,-1});
        dirs.put("E", new int[]{1,0}); dirs.put("W", new int[]{-1,0});
        dirs.put("NE", new int[]{1,1}); dirs.put("NW", new int[]{-1,1});
        dirs.put("SE", new int[]{1,-1}); dirs.put("SW", new int[]{-1,-1});
    }

    static Set<String> parseKey(List<String> lines) {
        Map<Integer, int[]> nodes = new HashMap<>();
        Set<String> bars = new HashSet<>();
        // Each line is a path: label dir label dir label ...
        for (String line : lines) {
            String[] tokens = line.trim().split("\\s+");
            // first token is a node label (integer)
            int curLabel = Integer.parseInt(tokens[0]);
            int[] curPos = nodes.getOrDefault(curLabel, new int[]{0,0});
            nodes.put(curLabel, curPos);
            for (int i = 1; i < tokens.length; i += 2) {
                String dir = tokens[i];
                int nextLabel = Integer.parseInt(tokens[i+1]);
                int[] d = dirs.get(dir);
                int[] nextPos = new int[]{curPos[0]+d[0], curPos[1]+d[1]};
                if (nodes.containsKey(nextLabel)) nextPos = nodes.get(nextLabel);
                else nodes.put(nextLabel, nextPos);
                // add bar
                String bar = Math.min(curPos[0],nextPos[0])+","+Math.min(curPos[1],nextPos[1])+"-"+Math.max(curPos[0],nextPos[0])+","+Math.max(curPos[1],nextPos[1]);
                bars.add(bar);
                curPos = nextPos; curLabel = nextLabel;
            }
        }
        // normalize: find min x and y
        // ... parse bars back and shift
        return bars;
    }
}

import java.io.*;
import java.util.*;

/*
We parse each key description as a rooted ordered tree encoded by:
- direction symbols: 0, 1, 2
- positive integers: labels of leaves/endpoints

Meaning:
A description is a set of root-to-leaf paths. Each path consists of directions and ends with an integer label.
Two descriptions represent the same key iff they define the same labeled trie/tree.

Input format (standard for this classic problem):
- First line: integer T, number of pairs
- For each pair:
    line/string A
    line/string B

Each description is a string containing characters '0','1','2' and integers.
Example tokenization:
  01 2 15 ...
But since exact whitespace style may vary, we scan character by character:
- sequences of digits are tokens
- if a token is exactly "0","1","2" and is followed by more path content, it is still just a token;
  all tokens before the final integer in one path are directions.
Descriptions are terminated by '#'.
This is the standard representation:
  paths are concatenated, each ending with a leaf label; entire description ends with '#'.

We reconstruct a trie:
- internal nodes have up to 3 outgoing edges labeled 0,1,2
- each path ends at a node with a leaf label
- conflicting structure/duplicate inconsistent labels => invalid but comparison still handled structurally

Canonical form:
For every node, canonical string = "(" + label-or-"-" + child0 + child1 + child2 + ")"
Two keys are SAME iff canonical forms equal.

Because the original statement excerpt is truncated, this implementation follows the common encoding:
description consists of many paths, each path written as a string of 0/1/2 followed by a positive integer,
and the whole description ends with '#'.

Example: 01 5 2 7 #  means paths "01"->5 and "2"->7.
Whitespace is ignored.
*/
public class Main {
    static class Node {
        Node[] ch = new Node[3];
        Integer label = null;
    }

    static class Parser {
        String s;
        int idx;

        Parser(String s) {
            this.s = s;
            this.idx = 0;
        }

        void skipWS() {
            while (idx < s.length() && Character.isWhitespace(s.charAt(idx))) idx++;
        }

        boolean done() {
            skipWS();
            return idx >= s.length();
        }

        String nextToken() {
            skipWS();
            if (idx >= s.length()) return null;
            char c = s.charAt(idx);
            if (c == '#') {
                idx++;
                return "#";
            }
            if (Character.isDigit(c)) {
                int j = idx;
                while (j < s.length() && Character.isDigit(s.charAt(j))) j++;
                String t = s.substring(idx, j);
                idx = j;
                return t;
            }
            // ignore unexpected separators/symbols
            idx++;
            return nextToken();
        }
    }

    static Node parseDescription(String line) {
        Parser p = new Parser(line);
        Node root = new Node();

        while (true) {
            String tok = p.nextToken();
            if (tok == null || tok.equals("#")) break;

            // This token starts a path. Since directions are 0/1/2 and final token is positive integer label,
            // we need to collect until a token not in {0,1,2} OR until we decide the last token is label.
            List<String> tokens = new ArrayList<>();
            tokens.add(tok);

            while (true) {
                String nt = p.nextToken();
                if (nt == null || nt.equals("#")) {
                    // last token in current collected sequence must be label
                    buildPath(root, tokens);
                    return root;
                }
                tokens.add(nt);

                // We don't know boundaries from truncated statement; standard interpretation:
                // each path is encoded as one token of directions (e.g. "012") followed by one integer label.
                // So if first token may itself be a direction-string, then second token is label.
                // Also sometimes directions may be split digitwise by whitespace, so we merge all leading 0/1/2 tokens
                // until final token > 2 or multi-digit.
                if (isLabelToken(tokens.get(tokens.size() - 1))) {
                    buildPath(root, tokens);
                    break;
                }
            }
        }

        return root;
    }

    static boolean isDirToken(String t) {
        return t.equals("0") || t.equals("1") || t.equals("2");
    }

    static boolean isLabelToken(String t) {
        if (t.length() > 1) return true;
        return !(t.equals("0") || t.equals("1") || t.equals("2"));
    }

    static void buildPath(Node root, List<String> tokens) {
        if (tokens.isEmpty()) return;
        String labelTok = tokens.get(tokens.size() - 1);
        int label = Integer.parseInt(labelTok);

        StringBuilder path = new StringBuilder();
        for (int i = 0; i + 1 < tokens.size(); i++) path.append(tokens.get(i));

        Node cur = root;
        for (int i = 0; i < path.length(); i++) {
            int d = path.charAt(i) - '0';
            if (d < 0 || d > 2) continue;
            if (cur.ch[d] == null) cur.ch[d] = new Node();
            cur = cur.ch[d];
        }
        cur.label = label;
    }

    static String canon(Node u) {
        if (u == null) return ".";
        StringBuilder sb = new StringBuilder();
        sb.append('(');
        if (u.label == null) sb.append('-');
        else sb.append(u.label);
        for (int i = 0; i < 3; i++) sb.append(canon(u.ch[i]));
        sb.append(')');
        return sb.toString();
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        List<String> lines = new ArrayList<>();
        String line;
        while ((line = br.readLine()) != null) lines.add(line);

        if (lines.isEmpty()) return;

        int ptr = 0;
        while (ptr < lines.size() && lines.get(ptr).trim().isEmpty()) ptr++;
        if (ptr >= lines.size()) return;

        int t;
        try {
            t = Integer.parseInt(lines.get(ptr).trim());
            ptr++;
        } catch (Exception e) {
            // Fallback: if no explicit T, process remaining lines in pairs
            t = (lines.size() - ptr) / 2;
        }

        StringBuilder out = new StringBuilder();
        for (int cs = 0; cs < t; cs++) {
            while (ptr < lines.size() && lines.get(ptr).trim().isEmpty()) ptr++;
            String a = ptr < lines.size() ? lines.get(ptr++) : "";
            while (ptr < lines.size() && lines.get(ptr).trim().isEmpty()) ptr++;
            String b = ptr < lines.size() ? lines.get(ptr++) : "";

            Node ta = parseDescription(a);
            Node tb = parseDescription(b);

            out.append(canon(ta).equals(canon(tb)) ? "SAME" : "DIFFERENT");
            if (cs + 1 < t) out.append('\n');
        }

        System.out.print(out.toString());
    }
}
